python3 << 'EOF'
from docx import Document
import os

docx_file = "From Commands to Conversation_ A Beginner's Guide to Vibe Coding.docx"
if os.path.exists(docx_file):
    try:
        doc = Document(docx_file)
        print('DOCX DOCUMENT CONTENT:')
        print('='*80)
        for para in doc.paragraphs:
            if para.text.strip():
                print(para.text)
    except Exception as e:
        print(f'Error: {e}')
else:
    print(f'File not found: {docx_file}')
EOF
